<script>
document.addEventListener('DOMContentLoaded',()=>{
  const modal=document.getElementById('deviceModal'),connector=document.getElementById('deviceConnector'),property=document.getElementById('deviceProperty'),area=document.getElementById('deviceArea');
  const filterDeviceAreas=(keep='')=>{const pid=String(property?.value||'');let visible=0;if(area){[...area.options].forEach((o,i)=>{if(i===0){o.hidden=false;o.disabled=false;return;}const ok=pid!==''&&String(o.dataset.propertyId||'')===pid;o.hidden=!ok;o.disabled=!ok;if(ok)visible++;});if(keep){const wanted=[...area.options].find(o=>String(o.value)===String(keep)&&!o.disabled);area.value=wanted?String(keep):'';}else if(area.selectedOptions[0]?.disabled)area.value='';}const help=document.getElementById('deviceAreaHelp');if(help)help.innerHTML=pid===''?'<strong>QUÉ espacio:</strong> selecciona primero la ubicación estructural.':(visible?`<strong>QUÉ espacio:</strong> ${visible} área(s) disponible(s) aquí.`:'No hay áreas aquí; el activo puede quedar directamente en la estructura.');};
  const applyConnectorRules=()=>{const option=connector.options[connector.selectedIndex],code=option?.dataset.code||'',name=option?.dataset.name||'',isZk=code==='zkteco'||code==='zkteco_biosecurity';document.getElementById('zkDeviceNotice').classList.toggle('d-none',!isZk);if(name&&!document.getElementById('deviceManaged').value)document.getElementById('deviceManaged').value=name;if(isZk){document.getElementById('deviceRole').value='managed_device';document.getElementById('deviceRole').disabled=true;document.getElementById('devicePath').value='via_platform';document.getElementById('devicePath').disabled=true;document.getElementById('deviceManaged').value=name;if(!document.getElementById('deviceNotes').value)document.getElementById('deviceNotes').value='Property Hub consulta este equipo a través del servidor ZKBioSecurity; no existe conexión directa al panel.';}else{document.getElementById('deviceRole').disabled=false;document.getElementById('devicePath').disabled=false;}};
  connector.addEventListener('change',applyConnectorRules);
  modal.addEventListener('show.bs.modal',event=>{const b=event.relatedTarget;let d={};if(b?.classList.contains('js-edit-device')){try{d=JSON.parse(b.dataset.json||'{}')}catch(e){d={}}}document.getElementById('deviceTitle').textContent=d.id?'Editar activo técnico':'Nuevo activo técnico';const defaults={deviceType:'access_controller',deviceRole:'managed_device',deviceStage:'installed',devicePath:'via_platform',deviceMode:'lan',deviceStatus:'unknown'};const map={deviceId:'id',deviceName:'name',deviceType:'device_type',deviceStage:'asset_stage',deviceProperty:'property_id',deviceArea:'area_id',deviceRole:'asset_role',deviceVendor:'vendor',deviceModel:'model',deviceLocation:'site_location_id',deviceConnector:'connector_instance_id',devicePath:'connection_path',deviceSerial:'serial_number',deviceFirmware:'firmware_version',deviceIp:'ip_address',deviceZone:'network_zone',deviceMode:'connectivity_mode',deviceManaged:'managed_by',deviceExternal:'external_id',deviceStatus:'status',deviceNotes:'connection_notes'};Object.entries(map).forEach(([el,key])=>{document.getElementById(el).value=d[key]??defaults[el]??'';});filterDeviceAreas(d.area_id||'');applyConnectorRules();});
  property?.addEventListener('change',()=>filterDeviceAreas());
  modal.querySelector('form').addEventListener('submit',()=>{document.getElementById('deviceRole').disabled=false;document.getElementById('devicePath').disabled=false;});
});

// presetNewDeviceContext
if(<?= $presetNew?'true':'false' ?>){const m=document.getElementById('deviceModal');if(m){document.getElementById('deviceProperty').value='<?= (int)$presetPropertyId ?>';filterDeviceAreas('<?= (int)$presetAreaId ?>');bootstrap.Modal.getOrCreateInstance(m).show();}}
</script>
<?php endif;?>
